    {
      "id": 1,
      "claim": "The population regression function (PRF) is the true conditional expectation of Y given X, i.e., a description of the data‑generating process.",
      "evidence": "Standard definition in econometrics/statistics: PRF = E[Y|X] and represents the underlying relationship.",
      "weight": 0.4,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The sample regression function (SRF) is the estimated regression line obtained from a finite sample.",
      "evidence": "SRF = fitted OLS line using sample data; it is an estimate of the PRF.",
      "weight": 0.3,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Option A is false because the PRF is not estimated; it is the true (unknown) model.",
      "evidence": "From step 1, PRF is the true relationship, not an estimate.",
      "weight": 0.1,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Option B is false because the SRF is used to infer the PRF, not the other way around.",
      "evidence": "From step 2, SRF estimates the PRF; inference runs from sample to population.",
      "weight": 0.1,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Option C is false because the PRF is unknown, so we cannot directly compare it to the SRF to assess model fit.",
      "evidence": "In practice the PRF cannot be observed; goodness‑of‑fit is assessed via residuals, R², etc., not by direct PRF‑SRF comparison.",
      "weight": 0.05,
      "depends_on": [1,2]
    },
    {
      "id": 6,
      "claim": "Option D is true: the PRF describes the process thought to generate the data.",
      "evidence": "Matches the definition in step 1.",
      "weight": 0.05,
      "depends_on": [1]
    }
  ],
